"""Test data of the PostgreSQL migration rehearsal (postgres-upgrade-e2e.sh).

Run inside the web container, as the argument of ``manage.py shell -c`` (the
shell's stdin path is not reliable through ``docker compose exec``), with
``REHEARSAL_ACTION`` set to:

``seed``         create records through the application's own models, across
                 the tables that matter (users, customers, sites, servers,
                 agents, telemetry and its history, Docker state, network
                 targets and measurements), in one transaction;
``fingerprint``  check that exactly those records exist and are related as
                 seeded, and print one line per table with a digest of every
                 column of every row. The rehearsal compares the output before
                 the migration with the output after the restore and after the
                 rollback: any lost, changed or re-typed value changes a digest.

The values are fixed, so the output is repeatable; none of them is a secret.
The agent's token is generated by the application and never leaves this script.
"""

import hashlib
import json
import os
import uuid
from datetime import datetime, timedelta
from datetime import timezone as dt_timezone
from decimal import Decimal

from django.apps import apps
from django.contrib.auth import get_user_model
from django.db import transaction

from apps.agents.services import create_agent
from apps.infrastructure.models import (
    DockerContainer,
    DockerHostState,
    Server,
    ServerTelemetry,
    ServerTelemetrySample,
)
from apps.inventory.models import Customer, Site
from apps.network.models import NetworkMeasurement, NetworkTarget

BASE = datetime(2026, 1, 15, 8, 30, tzinfo=dt_timezone.utc)
CUSTOMER = "Πελάτης Δοκιμής ü"  # non-ASCII on purpose

# Rows each table holds after seeding (the database starts empty).
EXPECTED_ROWS = {
    "auth.User": 1,
    "inventory.Customer": 1,
    "inventory.Site": 1,
    "infrastructure.Server": 1,
    "agents.Agent": 1,
    "infrastructure.ServerTelemetry": 1,
    "infrastructure.ServerTelemetrySample": 3,
    "infrastructure.DockerHostState": 1,
    "infrastructure.DockerContainer": 2,
    "network.NetworkTarget": 2,
    "network.NetworkMeasurement": 4,
}


def seed():
    with transaction.atomic():
        get_user_model().objects.create_user("rehearsal", email="rehearsal@example.invalid")
        customer = Customer.objects.create(name=CUSTOMER, notes="rehearsal ✓ line one\nline two")
        site = Site.objects.create(customer=customer, name="Rehearsal HQ", description="Rack 4")
        server = Server.objects.create(
            name="rehearsal-server",
            hostname="rehearsal.example.invalid",
            operating_system="Linux 6.8",
            ip_address="192.0.2.10",
            site=site,
            status=Server.Status.ONLINE,
            last_seen_at=BASE,
        )
        agent, _token = create_agent(server=server, name="rehearsal-agent")
        ServerTelemetry.objects.create(
            server=server,
            cpu_percent=12.625,
            memory_total_bytes=17_179_869_184,
            memory_used_bytes=6_442_450_944,
            memory_percent=37.5,
            disk_total_bytes=1_099_511_627_776,
            disk_used_bytes=412_316_860_416,
            disk_percent=37.5,
            uptime_seconds=9_876_543_210,
            collected_at=BASE,
            received_at=BASE + timedelta(seconds=1),
        )
        for minute in range(3):
            ServerTelemetrySample.objects.create(
                server=server,
                sampled_at=BASE + timedelta(minutes=minute),
                cpu_percent=10.5 + minute,
                memory_percent=40.25 + minute,
                disk_percent=37.5,
            )
        DockerHostState.objects.create(
            server=server,
            available=True,
            status=DockerHostState.Status.AVAILABLE,
            collected_at=BASE,
            received_at=BASE,
            last_discovered_at=BASE,
        )
        for index, (name, image) in enumerate((("web", "nginx:1.27"), ("db", "postgres:18-alpine"))):
            DockerContainer.objects.create(
                server=server,
                container_id=f"rehearsal{index:04d}",
                name=name,
                image=image,
                state=DockerContainer.State.RUNNING,
                health=DockerContainer.Health.HEALTHY,
                container_created_at=BASE,
                started_at=BASE,
                last_seen_at=BASE,
                received_at=BASE,
            )
        for name, address, protocol, port in (
            ("rehearsal-gateway", "192.0.2.1", NetworkTarget.Protocol.ICMP, None),
            ("rehearsal-web", "192.0.2.80", NetworkTarget.Protocol.TCP, 443),
        ):
            target = NetworkTarget.objects.create(
                name=name,
                hostname_or_ip=address,
                protocol=protocol,
                port=port,
                expected_sla_percentage=Decimal("99.95"),
                customer_name=CUSTOMER,
                site=site,
                circuit_identifier="CIR-0001",
                assigned_agent=agent,
            )
            for minute in range(2):
                NetworkMeasurement.objects.create(
                    id=uuid.uuid4(),
                    target=target,
                    agent=agent,
                    measured_at=BASE + timedelta(minutes=minute),
                    received_at=BASE + timedelta(minutes=minute, seconds=2),
                    success=True,
                    latency_ms=3.25 + minute,
                    packet_loss_percentage=0.0,
                    probe_count=4,
                    successful_probes=4,
                )


def check_relations():
    """The records are the ones seeded and still point at each other."""
    server = Server.objects.get(name="rehearsal-server")
    assert server.site.customer.name == CUSTOMER, "site or customer changed"
    assert server.agent.name == "rehearsal-agent", "agent no longer belongs to the server"
    assert server.telemetry.memory_total_bytes == 17_179_869_184, "telemetry changed"
    assert server.telemetry_samples.count() == 3, "telemetry history changed"
    assert server.docker_host.available, "Docker state changed"
    assert server.docker_containers.count() == 2, "containers changed"
    for target in NetworkTarget.objects.all():
        assert target.assigned_agent_id == server.agent.pk, "target lost its agent"
        assert target.site_id == server.site_id, "target lost its site"
        assert target.measurements.count() == 2, "measurements changed"
    assert NetworkTarget.objects.get(name="rehearsal-web").port == 443
    assert NetworkTarget.objects.get(name="rehearsal-gateway").expected_sla_percentage == Decimal("99.95")


def fingerprint():
    problems = []
    lines = []
    total = hashlib.sha256()
    total_rows = 0
    for label, expected in EXPECTED_ROWS.items():
        model = apps.get_model(label)
        rows = list(model.objects.order_by("pk").values())
        if len(rows) != expected:
            problems.append(f"{label}: {len(rows)} rows, expected {expected}")
        digest = hashlib.sha256(json.dumps(rows, sort_keys=True, default=str).encode()).hexdigest()
        total.update(digest.encode())
        total_rows += len(rows)
        lines.append(f"rehearsal {label} rows={len(rows)} sha256={digest}")
    try:
        check_relations()
        lines.append("rehearsal relations ok")
    except Exception as error:  # noqa: BLE001 - reported with the other findings
        problems.append(f"relations: {type(error).__name__}: {error}")
    if problems:
        raise SystemExit("rehearsal data is not as seeded:\n  " + "\n  ".join(problems))
    lines.append(f"rehearsal total rows={total_rows} sha256={total.hexdigest()}")
    print("\n".join(lines))


{"seed": seed, "fingerprint": fingerprint}[os.environ["REHEARSAL_ACTION"]]()
